// Station jump-in (13 §6, rule `facility.enter`): the station arrives near the planets it serves,
// ponderously, summoned by the captain whose attachment first brings it into the round. The summoner
// flies ahead to where it will come in (a guest jumps in there), so the eye is waiting at the spot
// (2026-10-12); then space folds and the station slides out, and a slow bloom spreads as it settles.
// The beacon pulses, bearing and planet rings are retired (27 E1: the flight already says it). The
// station's arrival is hero energy at rest (13 §6.1, 2026-10-13).
import { RULE } from '@shared/engine/pace';
import { HERO, HERO_GLOW } from '../../../chart/art/energy';
import { cmd, crewHoldMs, drawnR, one, phaseMs, pointOf, present, repeats } from '../../../chart/fx/commands';
import type { CommandCall, ManeuverDef } from '../../../chart/fx/types';
import { themeCmd } from '../commands';

export const stationJumpIn: ManeuverDef = {
  id: RULE.facilityEnter,
  title: 'Station jump-in',
  phase: {
    tell: (c) => {
      const f = one(c, 'facility') ?? one(c, 'subject');
      return f ? [cmd.ring({ at: f.at, r: drawnR(f) * 2.4, r1: drawnR(f) * 0.6, color: HERO, durS: 0.3, alpha: 0.35 })] : [];
    },
    gather: (c, m) => {
      const f = one(c, 'facility') ?? one(c, 'subject');
      if (!f) return [];
      const gather = phaseMs(m, 'gather');
      const fly = gather; // the flight alone (27 E1: no beacon pulses)
      const rest = crewHoldMs(m); // through the arrival, then a second with the summoner named (22 B9)
      const R = drawnR(f);
      const p = pointOf(f.at) ?? [f.node.world.x, f.node.world.y];
      // The spot beside where it comes in, on the side the summoner arrives from (or toward the star).
      const a = present(c, 'agent')[0];
      const from = (a && pointOf(a.at)) ?? [0, 0];
      const l = Math.hypot(from[0] - p[0], from[1] - p[1]) || 1;
      const spot: [number, number] = [p[0] + ((from[0] - p[0]) / l) * R * 1.9, p[1] + ((from[1] - p[1]) / l) * R * 1.9];
      const calls: CommandCall[] = [];
      if (a) calls.push(cmd.pursue({ pk: a.node.projectionKey, durS: fly / 1000, holdS: rest / 1000, backS: 0.8, to: spot, look: f.at, wake: 4 }));
      else {
        const away = c.away?.agent?.[0];
        if (away) calls.push(themeCmd.guest({ key: away.key, seed: away.seed, at: spot, face: p[0] >= spot[0] ? 1 : -1, durS: (gather + rest + 600) / 1000 }));
      }
      // Space folds as the flight ends (the flight is the call; this ring only repeats it).
      calls.push(repeats(cmd.ring({ at: f.at, r: R * 2.2, r1: R * 0.8, color: HERO, durS: 0.6, alpha: 0.5 }, gather - 600)));
      return calls;
    },
    act: (c) => {
      const f = one(c, 'facility') ?? one(c, 'subject');
      if (!f) return [];
      const r = drawnR(f);
      return [
        cmd.act(f.key, 'jump'),
        cmd.flare({ at: f.at, r, color: HERO_GLOW, scale: 1.3, linger: 2 }),
        cmd.ring({ at: f.at, r: r * 0.7, r1: r * 1.6, color: HERO_GLOW, durS: 1.2, alpha: 0.7 }),
      ];
    },
    land: (c) => {
      const f = one(c, 'facility') ?? one(c, 'subject');
      if (!f) return [];
      return [repeats(cmd.ring({ at: f.at, r: drawnR(f), r1: drawnR(f) * 1.2, color: HERO_GLOW, durS: 0.6, alpha: 0.5 }))];
    },
  },
};

  1	// The command registry (v1, 14 §2.8): named, weighted effects that a maneuver's phases issue. Each
  2	// seed command wraps one v0 effect (effects.ts, moves.ts, moments.ts) or a v1 mover (movers.ts), with
  3	// its weight and tier from the v0 director's volatility meter and budget (05 §5), its clock, and its
  4	// reduced-motion substitute (INV-20). A theme may override any of them by name (its `commands`).
  5	// The `cmd` builders below are how choreographies write calls with typed arguments.
  6	import { crewTimes } from '@shared/engine/maneuvers';
  7	import type { CanonicalKey } from '@shared/contracts/keys';
  8	import type { CastRole, Phase, PlannedManeuver } from '@shared/contracts/maneuver';
  9	import { GEOMETRY } from '@shared/engine/solar/version';
 10	import { fnv1a32 } from '@shared/hash';
 11	import { Container, Graphics } from 'pixi.js';
 12	import { lighten } from '../art/lit';
 13	import { easeInOut, easeOut, easeUndock, Flare, Ink, Ring, Spark, Support, Tractor, type Anchor, type FlareSpec, type Fx } from './effects';
 14	import { approachOf, ringApproachOf } from './approach';
 15	import { HoldFor, Sortie } from './movers';
 16	import { Pursue } from './moves';
 17	import type { FxHost } from './host';
 18	import type { CastView, CastViews, CommandCall, CommandDef } from './types';
 19	import { CYAN, REPEAT_VALUE, TRACTOR, TRACTOR_S } from './timing';
 20	
 21	// ---- Arguments ----
 22	
 23	/** A point effect: where, how big (world units), and its colour. */
 24	export interface PointArgs { at: Anchor; r: number; color?: number }
 25	export interface FlareArgs extends PointArgs {
 26	  scale?: number; linger?: number;
 27	  /** The completion flare: essential, never ducked, one bursting at a time. */
 28	  grand?: boolean;
 29	  /** Sparks in this colour (ornament: dropped unless calm). */
 30	  sparks?: number;
 31	  /** A grand flare waits for the previous one at most this long (s; the beat's end). */
 32	  capS?: number;
 33	}
 34	export interface RingArgs extends PointArgs { r1?: number; durS?: number; alpha?: number }
 35	export interface LineArgs { from: Anchor; to: Anchor; color?: number; durS?: number }
 36	export interface InkArgs extends LineArgs {
 37	  reverse?: boolean;
 38	  /** A held edge the ink reveals, released when it finishes (or at once under reduced motion). */
 39	  edge?: string;
 40	}
 41	export interface SparkArgs extends LineArgs { size?: number }
 42	export interface BeamArgs extends LineArgs { toR: number }
 43	/** A mover takes a node over; `start` is filled in by the runner (where the node is drawn now). */
 44	export interface MoverArgs { pk: string; start?: [number, number] }
 45	export interface PursueArgs extends MoverArgs {
 46	  /** Seconds to its goal: its own layout target, or with `to`, out to that point. */
 47	  durS: number;
 48	  /** A sortie: fly out to this live point, hold `holdS` nosed toward `look`, then back in `backS`. */
 49	  to?: Anchor; look?: Anchor; holdS?: number; backS?: number;
 50	  /** A sortie: stay parked this long after the hold (plate shut) before flying back, when the captain's next turn follows soon (P4). */
 51	  waitS?: number;
 52	  /**
 53	   * Other places to park, in order after `to` (22 B9): the first whose parked ship, with `clearPx`
 54	   * screen px round it for its own plate, stands clear of `avoid`'s plate is chosen, once, as it sets
 55	   * off, so a captain never parks over the plate of the work it is working.
 56	   */
 57	  toChoices?: Anchor[]; avoid?: string; clearPx?: number;
 58	  lift?: number; wake?: number; face?: boolean; ease?: 'inOut' | 'out' | 'undock';
 59	}
 60	export interface HoldArgs extends MoverArgs { durS: number }
 61	export interface ProtectArgs { eventKey: string; keys: CanonicalKey[]; durS: number }
 62	export interface InsigniaArgs extends PointArgs { shape: string; durS?: number; calledAt?: number }
 63	
 64	/** Every insignia lit this session (test hook `insignias()`, 23 D2): its shape, when it was asked for, and when it lit (`performance.now()`). */
 65	export const insigniaLog: { id: string; calledAt: number | null; litAt: number }[] = [];
 66	
 67	/** An anchor's point now (a live anchor may be gone: null). */
 68	export function pointOf(a: Anchor): [number, number] | null {
 69	  const p = typeof a === 'function' ? a() : a;
 70	  return p ? [p[0], p[1]] : null;
 71	}
 72	
 73	const fixed = (a: Anchor): [number, number] => pointOf(a) ?? [0, 0];
 74	const live = (a: Anchor | undefined) => () => (a === undefined ? null : pointOf(a));
 75	
 76	// ---- Typed call builders (for choreographies) ----
 77	
 78	const call = <A>(name: string) => (args: A, delayMs = 0): CommandCall => ({ cmd: name, args, delayMs });
 79	
 80	/** A call that repeats a meaning another cue gives (15 §8 effect-audit): it mutes first (27 E1). */
 81	export const repeats = (c: CommandCall): CommandCall => ('act' in c ? c : { ...c, value: REPEAT_VALUE });
 82	
 83	export const cmd = {
 84	  flare: call<FlareArgs>('flare'),
 85	  ring: call<RingArgs>('ring'),
 86	  ink: call<InkArgs>('ink'),
 87	  spark: call<SparkArgs>('spark'),
 88	  tractor: call<BeamArgs>('tractor'),
 89	  support: call<BeamArgs>('support'),
 90	  pursue: call<PursueArgs>('pursue'),
 91	  hold: call<HoldArgs>('hold'),
 92	  protect: call<ProtectArgs>('protect'),
 93	  insignia: call<InsigniaArgs>('insignia'),
 94	  /** An art act on one cast member's view (a jump, a break-up); `slot` the compound slot or slots it plays on (a volley's tenders dock together, 27 E6). */
 95	  act: (key: CanonicalKey, act: string, delayMs = 0, slot?: number | readonly number[]): CommandCall => ({ act: { key, act, ...(slot !== undefined ? { slot } : {}) }, ...(delayMs ? { delayMs } : {}) }),
 96	};
 97	
 98	/** A phase's length in a planned maneuver, in ms at 1× (0 when it has none). */
 99	export function phaseMs(m: PlannedManeuver, phase: Phase): number {
100	  return m.phases.find((p) => p.phase === phase)?.durMs ?? 0;
101	}
102	
103	/** Where a phase starts in a planned maneuver, in ms from its start (or where the last one ends). */
104	export function phaseAtMs(m: PlannedManeuver, phase: Phase): number {
105	  const p = m.phases.find((x) => x.phase === phase);
106	  return p ? p.atMs : m.phases.reduce((e, x) => Math.max(e, x.atMs + x.durMs), 0);
107	}
108	
109	// ---- A small kit for choreographies ----
110	
111	/**
112	 * How long a flying crew holds at the work, from the act's start (their arrival) until they leave
113	 * (22 B9, `crewTimes`): through the work, a second after it with their plates open, then the fold.
114	 */
115	export function crewHoldMs(m: PlannedManeuver): number {
116	  const t = crewTimes(m.phases);
117	  // A quiet turn (22 C6) isn't named, and a montage (27 E5b, P-24) names no crew, so neither holds a turn: the ships leave as the work ends.
118	  if (m.quiet || m.plate) return Math.max(0, workEndMs(m.phases) - t.openMs);
119	  return t.leaveMs - t.openMs;
120	}
121	
122	/** Where a maneuver's work ends: its land's end, else its act's (the crew's own measure, `crewTimes`). */
123	function workEndMs(phases: PlannedManeuver['phases']): number {
124	  const end = (p: string) => { const x = phases.find((q) => q.phase === p); return x ? x.atMs + x.durMs : undefined; };
125	  return end('land') ?? end('act') ?? 0;
126	}
127	
128	/** The first view of a cast part, if it's in the scene. */
129	export function one(c: CastViews, role: CastRole): CastView | undefined {
130	  return c[role]?.[0];
131	}
132	
133	/** A cast member's drawn radius now (world units): its floored size when zoomed out. */
134	export function drawnR(v: CastView): number {
135	  return v.drawnR?.() ?? v.node.world.r;
136	}
137	
138	/** Where a captain aims for a cast member: its host (a tender's station), else itself. */
139	export function aimOf(v: CastView): CastView {
140	  return v.host ?? v;
141	}
142	
143	/** A cast member still in the scene (not left this beat). */
144	export function present(c: CastViews, role: CastRole): CastView[] {
145	  return (c[role] ?? []).filter((v) => !v.gone);
146	}
147	
148	/** The turns off the work's side a sortie may park at instead (radians), in order, to keep off the work's plate (22 B9). */
149	const PARK_TURNS = [0.45, -0.45, 0.9, -0.9];
150	/** The ring's neighbouring slots a sortie may park at instead, in order, to keep off the work's plate (22 D6). */
151	const RING_TURNS = [1, -1, 2, -2];
152	/** A fan of this many radians (a strike run's spacing, 0.8) is one loiter slot round the ring (22 D6). */
153	const FAN_PER_SLOT = 0.8;
154	/** The room a parked ship keeps round it for its own plate, screen px (22 B9). */
155	const PARK_CLEAR_PX = 26;
156	
157	/**
158	 * A ship's sortie to work `target`: out over `outMs` to a point beside it, holding there `holdMs`
159	 * nosed toward it, then back to its own place over `backMs`. With the planet the work is on
160	 * (`around`, the cast's seat), it comes in on the work's side of that planet, outside its face (22
161	 * A10), turned a little either way if it would park over the work's plate (22 B9); without one, on
162	 * the side it comes from. It parks where it arrives.
163	 */
164	export function sortie(ship: CastView, target: CastView, outMs: number, holdMs: number, backMs: number, delayMs = 0, around?: CastView | null, fan = 0): CommandCall {
165	  // On a planet's loiter ring (22 D6): its slot nearest the work, a fanned ship that many slots round,
166	  // and the plate-dodging choices the neighbouring slots.
167	  const planned = around && !around.gone && around.key !== target.key ? around.node.loiterR : undefined;
168	  if (planned) {
169	    const pitch = () => 2 * Math.max(2 * drawnR(ship), 4 * GEOMETRY.shipR);
170	    // The ring as the scene draws it at this scale (its effective node's, `placeLoiterRings`), as at rest.
171	    const ringR = planned;
172	    const k = fan ? Math.sign(fan) * Math.ceil(Math.abs(fan) / FAN_PER_SLOT - 1e-9) : 0;
173	    const at = (more: number) => ringApproachOf(target.at, around!.at, ringR, pitch, k + more);
174	    const more = (fan ? RING_TURNS.filter((t) => Math.sign(t) === Math.sign(fan)) : RING_TURNS);
175	    return cmd.pursue({
176	      pk: ship.node.projectionKey, durS: outMs / 1000, holdS: holdMs / 1000, backS: backMs / 1000,
177	      to: at(0), toChoices: more.map(at), avoid: target.node.projectionKey, clearPx: PARK_CLEAR_PX, look: target.at, wake: 4,
178	    }, delayMs);
179	  }
180	  const from = pointOf(ship.at);
181	  const gap = () => drawnR(target) * 1.3 + drawnR(ship) * 1.6;
182	  const planet = around && !around.gone && around.key !== target.key ? around.at : null;
183	  const clear = planet ? () => drawnR(around!) + drawnR(ship) * 1.6 : undefined;
184	  const at = (turn: number) => approachOf(target.at, planet, from ?? target.at, gap, fan + turn, clear);
185	  return cmd.pursue({
186	    pk: ship.node.projectionKey, durS: outMs / 1000, holdS: holdMs / 1000, backS: backMs / 1000,
187	    // Round the work's side of its planet, a little either way if it would park over the work's plate (22 B9).
188	    // A fanned ship (a strike run's) turns only outward, away from its neighbours.
189	    to: at(0), ...(planet ? { toChoices: (fan ? PARK_TURNS.filter((t) => Math.sign(t) === Math.sign(fan)) : PARK_TURNS).map(at), avoid: target.node.projectionKey, clearPx: PARK_CLEAR_PX } : {}), look: target.at, wake: 4,
190	  }, delayMs);
191	}
192	
193	/**
194	 * A parking place clear of a node's plate (22 B9): of `choices` in order, the first whose ship (its
195	 * radius plus `clearPx` screen px for its own plate) misses the plate's rect; failing all, the one
196	 * whose centre stands furthest from it. Chosen on first ask once the plate is known, then kept, so
197	 * the ship never changes its mind mid-flight. No plate shown: the first.
198	 */
199	export function clearOfPlate(host: FxHost, choices: Anchor[], pk: string, clearPx: number, shipR: () => number): () => [number, number] | null {
200	  let pick: number | null = null;
201	  return () => {
202	    if (pick === null) {
203	      const r = host.plateWorld?.(pk) ?? null;
204	      if (!r) return pointOf(choices[0]!);
205	      const pad = shipR() + clearPx * host.px();
206	      // The clearance of a ship there: its distance outside the plate (inside: how deep, negative), less its room.
207	      const gapOf = (p: [number, number]) => {
208	        const dx = Math.max(r.x0 - p[0], 0, p[0] - r.x1);
209	        const dy = Math.max(r.y0 - p[1], 0, p[1] - r.y1);
210	        const inside = -Math.min(p[0] - r.x0, r.x1 - p[0], p[1] - r.y0, r.y1 - p[1]);
211	        return (dx || dy ? Math.hypot(dx, dy) : inside) - pad;
212	      };
213	      const pts = choices.map((c) => pointOf(c));
214	      const clear = pts.findIndex((p) => !!p && gapOf(p) > 0);
215	      pick = clear >= 0 ? clear : pts.reduce((best, p, i) => (p && (best < 0 || gapOf(p) > gapOf(pts[best]!)) ? i : best), -1);
216	      if (pick < 0) pick = 0;
217	    }
218	    return pointOf(choices[pick]!);
219	  };
220	}
221	
222	/** A point `dist` out from `at`, at a seeded angle (a retreat's heading): deterministic per maneuver. */
223	export function away(at: Anchor, seed: number, dist: number): [number, number] {
224	  const p = pointOf(at) ?? [0, 0];
225	  const a = ((seed % 360) / 180) * Math.PI;
226	  return [p[0] + Math.cos(a) * dist, p[1] + Math.sin(a) * dist];
227	}
228	
229	// ---- Effects only commands need ----
230	
231	/** A grand flare waiting for the previous one to settle (one grand burst at a time), then bursting. */
232	class LateFlare implements Fx {
233	  readonly kind = 'accent';
234	  readonly grand: boolean;
235	  private inner: Flare | null = null;
236	  private t = 0;
237	  constructor(private readonly make: () => Flare, private readonly wait: number, grand: boolean) {
238	    this.grand = grand;
239	    if (wait <= 1e-3) this.inner = make();
240	  }
241	  update(dt: number): boolean {
242	    if (this.inner) return this.inner.update(dt);
243	    this.t += dt;
244	    if (this.t >= this.wait) this.inner = this.make();
245	    return true;
246	  }
247	  duck(k: number): void {
248	    this.inner?.duck?.(k);
249	  }
250	  destroy(): void {
251	    this.inner?.destroy();
252	  }
253	}
254	
255	/**
256	 * An insignia (18 §5): an award's mark, drawn once over the piece that earned it. A small n-point
257	 * star (n from the shape id) inside a ring, fading up, turning a little, and fading out. Ornament.
258	 */
259	export class Insignia implements Fx {
260	  readonly kind = 'accent';
261	  private readonly root = new Container();
262	  private readonly g = new Graphics();
263	  private t = 0;
264	  private dim = 1;
265	  constructor(layer: Container, private readonly at: () => [number, number] | null, private readonly r: number, private readonly shape: string, private readonly color: number, private readonly dur: number, private readonly px: number) {
266	    this.g.blendMode = 'add';
267	    this.root.addChild(this.g);
268	    layer.addChild(this.root);
269	  }
270	  duck(k: number): void {
271	    this.dim = k;
272	  }
273	  update(dt: number): boolean {
274	    this.t += dt;
275	    const u = Math.min(1, this.t / this.dur);
276	    const p = this.at();
277	    if (p) this.root.position.set(p[0], p[1] - this.r * 1.6);
278	    const fade = Math.min(1, u / 0.15) * (1 - Math.max(0, (u - 0.75) / 0.25)) * this.dim;
279	    const n = 4 + (fnv1a32(this.shape) % 4);
280	    const s = this.r * 0.45 * (0.8 + 0.2 * easeOut(Math.min(1, u * 3)));
281	    const pts: number[] = [];
282	    for (let i = 0; i < n * 2; i++) {
283	      const a = -Math.PI / 2 + (i / (n * 2)) * Math.PI * 2 + u * 0.4;
284	      const k = i % 2 === 0 ? s : s * 0.45;
285	      pts.push(Math.cos(a) * k, Math.sin(a) * k);
286	    }
287	    this.g.clear()
288	      .circle(0, 0, s * 1.35).stroke({ width: 1.5 * this.px, color: this.color, alpha: 0.7 * fade })
289	      .poly(pts).fill({ color: lighten(this.color, 0.3), alpha: 0.85 * fade });
290	    return u < 1;
291	  }
292	  destroy(): void {
293	    this.root.destroy({ children: true });
294	  }
295	}
