297	// ---- The seed commands ----
298	
299	const EASE = { inOut: easeInOut, out: easeOut, undock: easeUndock } as const;
300	
301	/**
302	 * Weights, tiers and budgets follow the v0 director (05 §5): flares 1 (a grand one counts 3 and is
303	 * essential), moves 1.5, beams 1, lines and sparks 0.5, rings and marks 0.25, holds and protects 0.
304	 * Moves, lines, beams and protects are never cut (continuity); decoration is.
305	 */
306	export const SEED_COMMANDS: readonly CommandDef[] = Object.freeze([
307	  {
308	    name: 'flare', tier: 'narrative', weight: 1, value: 6, cuttable: true, clock: 'accent', reduced: 'ring',
309	    make(host: FxHost, a: FlareArgs): Fx {
310	      const layer = host.layer();
311	      const px = host.px();
312	      const spec: FlareSpec = { scale: a.scale ?? 1.6, linger: a.linger ?? 3, grand: a.grand, sparks: a.sparks };
313	      // Ornament off unless calm: lesser flares lose their sparks, and shrink while a grand one bursts.
314	      const plain = !spec.grand && !host.calm() ? { ...spec, sparks: undefined } : spec;
315	      const shown = !spec.grand && host.bursting() ? { ...plain, scale: 1 + (plain.scale - 1) * 0.7 } : plain;
316	      const wait = spec.grand ? host.grandSlot(0, a.capS ?? 4) : 0;
317	      return new LateFlare(() => {
318	        const [x, y] = fixed(a.at);
319	        return new Flare(layer, x, y, a.r, a.color ?? CYAN, shown, px);
320	      }, wait, !!spec.grand);
321	    },
322	  } satisfies CommandDef<FlareArgs>,
323	  {
324	    name: 'ring', tier: 'narrative', weight: 0.25, value: 1.5, cuttable: true, clock: 'accent', reduced: 'same',
325	    make(host: FxHost, a: RingArgs): Fx {
326	      const [x, y] = fixed(a.at);
327	      return new Ring(host.layer(), x, y, a.r, a.r1 ?? a.r * 1.4, a.color ?? CYAN, a.durS ?? 0.9, host.px(), a.alpha ?? 0.8);
328	    },
329	  } satisfies CommandDef<RingArgs>,
330	  {
331	    name: 'ink', tier: 'narrative', weight: 0.5, value: 5, cuttable: false, clock: 'travel', reduced: 'snap',
332	    make(host: FxHost, a: InkArgs): Fx {
333	      const scene = host.stage();
334	      if (a.edge) scene.holdEdge(a.edge);
335	      const done = a.edge ? () => scene.releaseEdge(a.edge!) : undefined;
336	      return new Ink(host.layer(), [a.from, a.to], a.color ?? CYAN, a.durS ?? 1, host.px(), a.reverse ?? false, done);
337	    },
338	  } satisfies CommandDef<InkArgs>,
339	  {
340	    name: 'spark', tier: 'narrative', weight: 0.5, value: 3, cuttable: true, clock: 'accent', reduced: 'skip',
341	    make(host: FxHost, a: SparkArgs): Fx {
