436	 * The call to make under reduced motion (INV-20): the same call, a ring where it was, another
437	 * command, or null to skip it. `snap` is a skip whose end state the scene already shows; an ink
438	 * that was revealing a held edge releases it at once.
439	 */
440	export function reducedCall(def: CommandDef, c: { cmd: string; args: unknown; delayMs?: number; value?: number }, host: FxHost): { cmd: string; args: unknown; delayMs?: number; value?: number } | null {
441	  const r = def.reduced;
442	  if (r === 'same') return c;
443	  if (r === 'skip') return null;
444	  if (r === 'snap') {
445	    const edge = (c.args as Partial<InkArgs>)?.edge;
446	    if (edge) host.stage().releaseEdge(edge);
447	    return null;
448	  }
449	  if (r === 'ring') {
450	    const a = c.args as Partial<PointArgs & BeamArgs>;
451	    const at = a.at ?? a.to ?? a.from;
452	    if (at === undefined) return null;
453	    const r0 = (a.r ?? a.toR ?? 12 * host.px()) * 1.2;
454	    return { cmd: 'ring', args: { at, r: r0, r1: r0, color: a.color ?? CYAN, durS: 0.9, alpha: 0.9 } satisfies RingArgs, delayMs: c.delayMs };
455	  }
456	  return { ...c, cmd: r.use };
457	}

