        this.move(scene, pk, make, start, 0, owner, meta);
      }));
      return;
    }
    const f = make(start);
    this.movers.set(pk, f);
    this.add(f, meta);
  }

  retire(f: Fx): void {
    if (this.dead.has(f)) return;
