  private play(scene: GraphScene, ctx: FxBeat, m: PlannedManeuver, s: number, eng: Engagement, before: Set<string>, revealed: Set<string>, lands: Map<string, Land>, near?: ReadonlyMap<CanonicalKey, number>): void {
