const ri = Math.round;

/** Every built item's saving per pod: before is a re-schedule with the item's change undone, now is today's. */
export function buildBuilt(inputs: EngineInputs = {}): BuiltRow[] {
  const rows: BuiltRow[] = [];
  for (const item of BUILT) {
    for (const rp of resolvePods()) {
      // Items built before the director keep measuring what they measured: both runs undirected.
      // Items built before rising tempo (27 E8) run both schedules without it, so their rows stay as measured.
      const base: EngineInputs = { ...(item.directs ? inputs : { ...inputs, direct: false }), ...(item.rises ? {} : { risingTempo: false as const }), ...(item.late ? {} : { lateMontage: false as const }), ...item.both };
      // Items built before the sector sweep (27 E7) run both schedules without it, so their rows stay as measured.
      const rules = item.sweeps ? [...PACE_RULES] : PACE_RULES.filter((r) => r.id !== RULE.regionSweep);
      const beforeMs = ri(scheduleOf(rp.h, rp.scene, rp.tz, { ...base, ...item.inputs, ...(item.before ? { rules: item.before([...rules]) } : item.sweeps ? {} : { rules: [...rules] }) }).wallMs);
      const nowMs = ri(scheduleOf(rp.h, rp.scene, rp.tz, { ...base, ...(item.after ? { rules: item.after([...rules]) } : item.sweeps ? {} : { rules: [...rules] }) }).wallMs);
      const savedMs = beforeMs - nowMs;
      const estimateMs = item.estimateMs[rp.label] ?? 0;
      rows.push({ id: item.id, pod: rp.label, beforeMs, nowMs, savedMs, estimateMs, diffMs: savedMs - estimateMs });
    }
  }
  return rows;
}

const sec = (ms: number) => (ms / 1000).toFixed(1);

/** The `## Built` section appended to the ledger's markdown. */
export function renderBuilt(rows: BuiltRow[]): string {
  const o: string[] = ['## Built', ''];
  o.push('What each built E item saves per pod: a real re-schedule with the item\'s change undone (before) against today\'s rules (now), beside C2\'s estimate (`npm run pacing -- --candidates`). Positive means shorter.', '');
  o.push('| Item | Pod | Before s | Now s | Saved s | C2\'s estimate s | Difference s |', '|---|---|---|---|---|---|---|');
  for (const r of rows) {
    const name = BUILT.find((b) => b.id === r.id)?.name ?? '';
    o.push(`| ${r.id} ${name} | ${r.pod} | ${sec(r.beforeMs)} | ${sec(r.nowMs)} | ${sec(r.savedMs)} | ${sec(r.estimateMs)} | ${sec(r.diffMs)} |`);
  }
  o.push('');
  return o.join('\n');
}
// `npm run pacing`: write the pacing ledger (docs/progress/v1.4/pacing-ledger.md and .json). Read-only
// over the engine. `--candidates` (C2) appends the Candidates section and writes pacing-candidates.json.
// `--profile <id>` (C4b) runs the engine on that device profile's pacing budget and writes
// `pacing-ledger.<id>.md/.json` beside the others; without it the output is the desktop run, unchanged.
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { BUNDLED } from '../src/shared/profile/bundled';
import { buildBuilt, renderBuilt } from './pacing-built';
import { buildCandidates, renderCandidates } from './pacing-candidates';
import { buildLedger, renderMarkdown, type EngineInputs } from './pacing-ledger';

const dir = resolve(__dirname, '../docs/progress/v1.4');
mkdirSync(dir, { recursive: true });
const at = process.argv.indexOf('--profile');
const id = at >= 0 ? process.argv[at + 1] : undefined;
const profile = id === undefined ? undefined : (BUNDLED as Record<string, EngineInputs['profile']>)[id];
if (at >= 0 && !profile) {
  console.error(`--profile needs one of: ${Object.keys(BUNDLED).join(', ')}`);
  process.exit(1);
}
const inputs: EngineInputs = profile ? { profile } : {};
const sfx = profile ? `.${id}` : '';
const ledger = buildLedger(inputs);
let md = renderMarkdown(ledger);
if (process.argv.includes('--candidates')) {
  const cands = buildCandidates(inputs);
  md += '\n' + renderCandidates(cands);
  const built = buildBuilt(inputs);
  md += '\n' + renderBuilt(built);
  writeFileSync(resolve(dir, `pacing-built${sfx}.json`), JSON.stringify(built, null, 2) + '\n');
  writeFileSync(resolve(dir, `pacing-candidates${sfx}.json`), JSON.stringify(cands, null, 2) + '\n');
}
writeFileSync(resolve(dir, `pacing-ledger${sfx}.json`), JSON.stringify(ledger, null, 2) + '\n');
writeFileSync(resolve(dir, `pacing-ledger${sfx}.md`), md + '\n');
for (const p of ledger.pods) console.log(`${p.label}: app ${(p.story.wallMs / 1000).toFixed(1)} s (story time); recorded ${(p.wallMs / 1000).toFixed(1)} s (uncapped ${(p.uncappedMs / 1000).toFixed(1)} s)`);

