    // Rates only rescale wall time: the schedule itself is in 1× ms.
    expect(sch.totalMs / 0.5).toBeCloseTo(sch.totalMs * 2, 6);
    expect(sch.totalMs / 0.25).toBeCloseTo(sch.totalMs * 4, 6);
